function flattenServiceTaxonomy(nodes,path=[]){nodes.forEach(node=>{const next=path.concat(node.label);if(node.children&&node.children.length)flattenServiceTaxonomy(node.children,next);else scpTaxonomyServices.push({label:node.label,path})})}
flattenServiceTaxonomy(scpServiceTaxonomy);
