const taxonomyStopWords=new Set(['para','con','por','del','las','los','una','uno','unos','unas','desde','hasta','sobre','tipo','tipos','mediante','segun','según','incluye','incluido','incluida','incluidos','incluidas','sus','cada','como','entre','ante','durante','dentro','general','completo','completa','servicio','servicios','profesional','profesionales','personalizado','personalizada']);
function legacyAreasForSector(sector){const s=normalize(sector);if(s.includes('salud'))return ['salud'];if(s.includes('bienestar'))return ['bienestar'];if(s.includes('desarrollo personal'))return ['bienestar','otros'];if(s.includes('derecho')||s.includes('abogacia'))return ['tramites'];if(s.includes('tramites')||s.includes('gestoria')||s.includes('documentacion'))return ['tramites'];if(s.includes('vivienda')||s.includes('inmobiliaria'))return ['vivienda'];if(s.includes('academia')||s.includes('formacion'))return ['academia','otros'];return null}
function meaningfulTokens(value){return normalize(value).split(' ').filter(word=>word.length>2&&!taxonomyStopWords.has(word))}
function similarServiceCard(item,label){const searchable=normalize([item.title||'',item.name||'',item.description||'',item.keywords||'',item.areaId||'',item.serviceId||'',serviceById(item.serviceId)?.label||'',areaById(item.areaId)?.label||''].join(' '));const tokens=[...new Set(meaningfulTokens(label))];if(!tokens.length)return false;const matching=tokens.filter(token=>searchable.includes(token)).length;if(tokens.length===1)return matching===1;return matching>=Math.max(2,Math.ceil(tokens.length*.35))}

