const areaById=id=>areas.find(area=>area.id===id),serviceById=id=>services.find(service=>service.id===id);
const status=document.getElementById('scp-demo-search-status'),demandCount=document.getElementById('scp-demo-demand-count'),offerCount=document.getElementById('scp-demo-offer-count'),empty=document.getElementById('scp-demo-empty'),clearButton=document.getElementById('scp-clear-filters'),serviceTitle=document.getElementById('scp-service-list-title'),areaPageLink=document.getElementById('scp-area-page-link');
const dialog=document.getElementById('scp-demo-dialog'),dialogTitle=document.getElementById('scp-demo-dialog-title'),dialogCopy=document.getElementById('scp-demo-dialog-copy'),dialogCta=document.getElementById('scp-demo-dialog-cta');
let manualArea=null,manualService=null,selectedCatalogService=null;
function resolveSearchArea(query){return searchAreas.find(area=>[area.label,...area.aliases].some(term=>query===normalize(term)||query.includes(normalize(term))))||null}
function resolvePickerService(query){
 const items=searchAreas.flatMap(area=>area.services);
 return items.sort((a,b)=>Math.max(...b.aliases.map(x=>normalize(x).length))-Math.max(...a.aliases.map(x=>normalize(x).length))).find(item=>[item.label,...item.aliases].some(term=>{const n=normalize(term);return query===n||query.includes(n)}))||null
}
function resolveArea(query){return areas.find(area=>area.aliases.some(alias=>query===normalize(alias)||query.includes(normalize(alias))))||null}
function resolveService(query,areaId){
 const candidates=services.filter(service=>!areaId||service.area===areaId).sort((a,b)=>Math.max(...b.aliases.map(x=>x.length))-Math.max(...a.aliases.map(x=>x.length)));
 return candidates.find(service=>[service.label,...service.aliases].some(term=>{const n=normalize(term);return query===n||query.includes(n)}))||null
}
function queryState(){
 const query=normalize(serviceInput.value);
 if(selectedCatalogService&&query===normalize(selectedCatalogService.label)){
  const legacyService=resolvePickerService(query);
  const legacyParent=legacyService?searchAreas.find(area=>area.services.includes(legacyService)):null;
  const areaIds=legacyParent?.categoryIds||legacyAreasForSector(selectedCatalogService.path[0]);
  return {areaIds,serviceIds:legacyService?.filterIds||null,areaId:areaIds?.[0]||null,serviceId:null,taxonomyService:legacyService?null:selectedCatalogService,freeQuery:''}
 }
 if(query){
  const exactGroup=searchAreas.find(area=>normalize(area.label)===query);
  if(exactGroup)return {areaIds:exactGroup.categoryIds,areaId:exactGroup.categoryIds[0],serviceId:null,freeQuery:''};
  const item=resolvePickerService(query);
  if(item){const parent=searchAreas.find(area=>area.services.includes(item));return {areaIds:parent.categoryIds,serviceIds:item.filterIds,areaId:parent.categoryIds[0],serviceId:null,freeQuery:''}}
  const group=resolveSearchArea(query);
  if(group)return {areaIds:group.categoryIds,areaId:group.categoryIds[0],serviceId:null,freeQuery:''};
  const area=resolveArea(query),service=resolveService(query,area?.id||null);
  return {areaIds:service?[service.area]:(area?[area.id]:null),areaId:service?.area||area?.id||null,serviceId:service?.id||null,freeQuery:service||area?'':query}
 }
 return {areaIds:manualService?[serviceById(manualService)?.area]:(manualArea?[manualArea]:null),areaId:manualService?serviceById(manualService)?.area:manualArea,serviceId:manualService,freeQuery:''}
}
function cardMatches(item,state,location){
 if(state.areaIds&&state.areaIds.length&&!state.areaIds.includes(item.areaId))return false;
 if(state.serviceIds&&state.serviceIds.length&&!state.serviceIds.includes(item.serviceId))return false;
 if(state.serviceId&&item.serviceId!==state.serviceId)return false;
 if(state.taxonomyService&&!similarServiceCard(item,state.taxonomyService.label))return false;
 if(state.freeQuery&&!similarServiceCard(item,state.freeQuery))return false;
 const place=normalize(item.ubicacion);if(location&&!place.includes(location)&&!(location==='internacional'&&/online|francia|colombia|portugal/.test(place)))return false;
 return true
}
function selectCatalogService(service){
 selectedCatalogService=service;serviceInput.value=service.label;servicePickerDetails.open=false;render();scrollToMarket()
}
function renderTaxonomyNodes(nodes,container,depth=[],path=[]){
 nodes.forEach((node,index)=>{
  const key=depth.concat(index).join('.'),fullPath=path.concat(node.label);
  if(node.children&&node.children.length){
   const group=document.createElement('div');group.className='scp-taxonomy-node scp-taxonomy-node--level-'+(depth.length+1);
   const toggle=document.createElement('button');toggle.type='button';toggle.className='scp-taxonomy-toggle';toggle.setAttribute('aria-expanded',String(expandedTaxonomyNodes.has(key)));
   const label=document.createElement('span');label.className='scp-taxonomy-label';label.textContent=node.label;
   const arrow=document.createElement('span');arrow.className='scp-taxonomy-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent=expandedTaxonomyNodes.has(key)?'▾':'▸';
   toggle.append(label,arrow);toggle.addEventListener('click',()=>{if(expandedTaxonomyNodes.has(key))expandedTaxonomyNodes.delete(key);else expandedTaxonomyNodes.add(key);renderServicePicker()});group.append(toggle);
   if(expandedTaxonomyNodes.has(key)){const children=document.createElement('div');children.className='scp-taxonomy-children';renderTaxonomyNodes(node.children,children,depth.concat(index),fullPath);group.append(children)}
   container.append(group)
  }else{
   const service={label:node.label,path};const button=document.createElement('button');button.type='button';button.className='scp-taxonomy-service';button.textContent=node.label;button.addEventListener('click',()=>selectCatalogService(service));container.append(button)
  }
 })
}
function renderServicePicker(){
 servicePicker.replaceChildren();const query=normalize(serviceInput.value);
 if(query&&!selectedCatalogService){
  scpTaxonomyServices.filter(service=>normalize(service.label).includes(query)).forEach(service=>{
   const result=document.createElement('button');result.type='button';result.className='scp-taxonomy-result';
   const title=document.createElement('span');title.className='scp-taxonomy-result__title';title.textContent=service.label;
   const route=document.createElement('small');route.className='scp-taxonomy-result__route';route.textContent=service.path.join(' > ');
   result.append(title,route);result.addEventListener('click',()=>selectCatalogService(service));servicePicker.append(result)
  });return
 }
 renderTaxonomyNodes(scpServiceTaxonomy,servicePicker)
}
